  44→@AndroidEntryPoint
  45→class LedgerActivity : ComponentActivity() {
  46→    @Inject lateinit var database: Lazy<TimeAgentDatabase>
  47→    companion object {
  48→        const val EXTRA_CAPTURE_ID = "ledger_capture_id"
  49→        const val EXTRA_ACTION = "ledger_action"
  50→        const val ACTION_IGNORE = "ignore"
  51→    }
  52→
  53→    override fun onCreate(savedInstanceState: Bundle?) {
  54→        super.onCreate(savedInstanceState)
  55→        if (!recoverPersonalDataBeforeOpen()) return
  56→        val repo = LedgerRepository(database.get())
  57→        val captureId = intent?.getStringExtra(EXTRA_CAPTURE_ID)
  58→        val ignore = intent?.getStringExtra(EXTRA_ACTION) == ACTION_IGNORE
  59→        setContent {
  60→            TimeAgentTheme {
  61→                androidx.activity.compose.BackHandler { returnToButler() }
  62→                LedgerApp(
  63→                    repository = repo,
  64→                    initialCaptureId = captureId,
  65→                    initialIgnore = ignore,
  66→                    onClose = ::returnToButler,
  67→                )
  68→            }
  69→        }
  70→    }
  71→
  72→    override fun onNewIntent(intent: Intent) {
  73→        super.onNewIntent(intent)
  74→        setIntent(intent)
  75→        recreate()
  76→    }
  77→
  78→}
  79→
  80→@OptIn(ExperimentalMaterial3Api::class)
  81→@Composable
  82→private fun LedgerApp(
  83→    repository: LedgerRepository,
  84→    initialCaptureId: String?,
  85→    initialIgnore: Boolean,
  86→    onClose: () -> Unit,
  87→) {
  88→    val context = LocalContext.current
  89→    val scope = rememberCoroutineScope()
  90→    val zone = repository.zone
  91→    val currentMonth = remember(zone) { YearMonth.now(zone) }
  92→
  93→    var snapshot by remember { mutableStateOf<LedgerSnapshot?>(null) }
  94→    var busy by remember { mutableStateOf(false) }
  95→    var error by remember { mutableStateOf<String?>(null) }
  96→    var notice by remember { mutableStateOf<String?>(null) }
  97→    var tab by rememberSaveable { mutableIntStateOf(0) }
  98→    var statusTick by remember { mutableIntStateOf(0) }
  99→    var captureEnabled by remember { mutableStateOf(LedgerSettings.enabled(context)) }
 100→
 101→    var selectedMonth by rememberSaveable { mutableStateOf(currentMonth.toString()) }
 102→    var allMonths by rememberSaveable { mutableStateOf(false) }
 103→
 104→    var captureTarget by remember { mutableStateOf<PaymentCaptureEntity?>(null) }
 105→    var ignoreTarget by remember { mutableStateOf<PaymentCaptureEntity?>(null) }
 106→    var deleteTarget by remember { mutableStateOf<LedgerTransactionEntity?>(null) }
 107→    var transactionEditing by remember { mutableStateOf<LedgerTransactionEntity?>(null) }
 108→    var transactionNew by remember { mutableStateOf(false) }
 109→    var accountEditing by remember { mutableStateOf<LedgerAccountEntity?>(null) }
 110→    var accountNew by remember { mutableStateOf(false) }
 111→    var categoryEditing by remember { mutableStateOf<LedgerCategoryEntity?>(null) }
 112→    var categoryNew by remember { mutableStateOf(false) }
 113→    var archiveAccountTarget by remember { mutableStateOf<LedgerAccountEntity?>(null) }
 114→    var archiveCategoryTarget by remember { mutableStateOf<LedgerCategoryEntity?>(null) }
 115→    var deepLinkHandled by rememberSaveable { mutableStateOf(false) }
 116→
 117→    val accessGranted = remember(statusTick) { LedgerSettings.notificationAccessGranted(context) }
 118→    val postAllowed = remember(statusTick) { LedgerSettings.notificationsAllowed(context) }
 119→
 120→    fun runAction(success: String? = null, block: suspend () -> Unit) {
 121→        if (busy) return
 122→        busy = true
 123→        error = null
 124→        scope.launch {
 125→            try {
 126→                block()
 127→                if (success != null) notice = success
 128→            } catch (e: Exception) {
 129→                error = e.message?.takeIf { it.isNotBlank() } ?: "操作失败"
 130→            } finally {
 131→                busy = false
 132→            }
 133→        }
 134→    }
 135→
 136→    LaunchedEffect(repository) {
 137→        repository.observe()
 138→            .catch { e -> error = e.message ?: "读取账本失败" }
 139→            .collect { snapshot = it }
 140→    }
 141→
 142→    val data = snapshot
 143→    val visibleTransactions = remember(data, selectedMonth, allMonths) {
 144→        val all = data?.transactions.orEmpty()
 145→        if (allMonths) all else all.filter {
 146→            YearMonth.from(Instant.ofEpochMilli(it.occurredAt).atZone(zone)).toString() == selectedMonth
 147→        }
 148→    }
 149→    val totals = remember(visibleTransactions) { repository.totals(visibleTransactions) }
 150→
 151→    LaunchedEffect(initialCaptureId, data, initialIgnore) {
 152→        if (deepLinkHandled || initialCaptureId == null) return@LaunchedEffect
 153→        val current = data ?: return@LaunchedEffect
 154→        val capture = current.captures.firstOrNull {
 155→            it.id == initialCaptureId && it.status == PaymentCaptureEntity.Status.PENDING
 156→        }
 157→        if (capture != null) {
 158→            deepLinkHandled = true
 159→            if (initialIgnore) ignoreTarget = capture else captureTarget = capture
 160→        } else if (current.captures.any { it.id == initialCaptureId }) {
 161→            deepLinkHandled = true
 162→        }
 163→    }
 164→
 165→    val settingsLauncher = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) {
 166→        statusTick++
 167→    }
 168→    val permissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) {
 169→        statusTick++
 170→    }
 171→    val importLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
 172→        if (uri != null) {
 173→            runAction {
 174→                val bytes = context.contentResolver.openInputStream(uri)?.use { stream ->
 175→                    val output = ByteArrayOutputStream()
 176→                    val chunk = ByteArray(8192)
 177→                    var total = 0
 178→                    while (true) {
 179→                        val read = stream.read(chunk)
 180→                        if (read <= 0) break
 181→                        total += read
 182→                        require(total <= 20 * 1024 * 1024) { "账单文件过大（上限 20MB）" }
 183→                        output.write(chunk, 0, read)
 184→                    }
 185→                    output.toByteArray()
 186→                } ?: throw IllegalStateException("无法读取所选文件")
 187→                val result = repository.importBills(bytes)
 188→                notice = result.summary()
 189→            }
 190→        }
 191→    }
 192→    val exportLauncher = rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("text/csv")) { uri ->
 193→        val current = snapshot
 194→        if (uri != null && current != null) {
 195→            runAction("已导出 CSV") {
 196→                val rows = current.transactions.filter {
 197→                    allMonths || YearMonth.from(Instant.ofEpochMilli(it.occurredAt).atZone(zone)).toString() == selectedMonth
 198→                }
 199→                val csv = repository.exportCsv(rows, current.accounts, current.categories, current.captures)
 200→                context.contentResolver.openOutputStream(uri)?.bufferedWriter(Charsets.UTF_8)?.use { it.write(csv) }
 201→                    ?: throw IllegalStateException("无法写入所选文件")
 202→            }
 203→        }
 204→    }
 205→
 206→    Scaffold(
 207→        topBar = {
 208→            TopAppBar(
 209→                title = { Text("账本") },
 210→                navigationIcon = { TextButton(onClick = onClose, enabled = !busy) { Text("返回") } },
 211→                actions = {
 212→                    TextButton(onClick = { runAction("已撤销") { repository.undoLastAction() } }, enabled = !busy) { Text("撤销") }
 213→                    TextButton(onClick = { runAction("已重做") { repository.redoLastAction() } }, enabled = !busy) { Text("重做") }
 214→                },
 215→            )
 216→        },
 217→    ) { padding ->
 218→        Column(Modifier.fillMaxSize().padding(padding)) {
 219→            TabRow(selectedTabIndex = tab) {
 220→                listOf("待确认", "账本", "账户与分类").forEachIndexed { index, title ->
 221→                    Tab(selected = tab == index, onClick = { tab = index }, text = { Text(title) })
 222→                }
 223→            }
 224→            error?.let {
 225→                NoticeBar(it, true) { error = null }
 226→            }
 227→            notice?.let {
 228→                NoticeBar(it, false) { notice = null }
 229→            }
 230→            if (data == null) {
 231→                Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
 232→                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
 233→                        CircularProgressIndicator()
 234→                        Spacer(Modifier.height(8.dp))
 235→                        Text("正在读取本地账本…", style = MaterialTheme.typography.bodySmall)
 236→                    }
 237→                }
 238→            } else {
 239→                when (tab) {
 240→                    0 -> PendingTab(
 241→                        data = data,
 242→                        zone = zone,
 243→                        busy = busy,
 244→                        captureEnabled = captureEnabled,
 245→                        accessGranted = accessGranted,
 246→                        postAllowed = postAllowed,
 247→                        onToggleCapture = { value ->
 248→                            captureEnabled = value
 249→                            LedgerSettings.setEnabled(context, value)
 250→                            statusTick++
 251→                            notice = when {
 252→                                !value -> "自动捕获已关闭"
 253→                                !accessGranted -> "本地开关已打开；还需在系统设置中授予通知使用权"
 254→                                else -> "自动捕获已开启；不会回放历史通知"
 255→                            }
 256→                        },
 257→                        onOpenSettings = {
 258→                            settingsLauncher.launch(Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS))
 259→                        },
 260→                        onRequestPermission = {
 261→                            if (Build.VERSION.SDK_INT >= 33 &&
 262→                                context.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED
 263→                            ) {
 264→                                permissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
 265→                            } else {
 266→                                val intent = Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS)
 267→                                    .putExtra(Settings.EXTRA_APP_PACKAGE, context.packageName)
 268→                                settingsLauncher.launch(intent)
 269→                            }
 270→                        },
 271→                        onImport = {
 272→                            importLauncher.launch(arrayOf("text/*", "application/octet-stream", "application/vnd.ms-excel"))
 273→                        },
 274→                        onManual = {
 275→                            transactionEditing = null
 276→                            transactionNew = true
 277→                        },
 278→                        onConfirm = { captureTarget = it },
 279→                        onIgnore = { ignoreTarget = it },
 280→                        onSetup = { tab = 2 },
 281→                    )
 282→
 283→                    1 -> LedgerTab(
 284→                        transactions = visibleTransactions,
 285→                        accounts = data.accounts,
 286→                        categories = data.categories,
 287→                        totals = totals,
 288→                        zone = zone,
 289→                        busy = busy,
 290→                        allMonths = allMonths,
 291→                        selectedMonth = selectedMonth,
 292→                        currentMonth = currentMonth.toString(),
 293→                        onThisMonth = {
 294→                            allMonths = false
 295→                            selectedMonth = currentMonth.toString()
 296→                        },
 297→                        onAll = { allMonths = true },
 298→                        onPreviousMonth = {
 299→                            selectedMonth = YearMonth.parse(selectedMonth).minusMonths(1).toString()
 300→                        },
 301→                        onNextMonth = {
 302→                            selectedMonth = YearMonth.parse(selectedMonth).plusMonths(1).toString()
 303→                        },
 304→                        onManual = {
 305→                            transactionEditing = null
 306→                            transactionNew = true
 307→                        },
 308→                        onEdit = {
 309→                            transactionNew = false
 310→                            transactionEditing = it
 311→                        },
 312→                        onDelete = { deleteTarget = it },
 313→                        onExport = {
 314→                            exportLauncher.launch("账本-${if (allMonths) "全部" else selectedMonth}.csv")
 315→                        },
 316→                    )
 317→
 318→                    else -> SetupTab(
 319→                        data = data,
 320→                        busy = busy,
 321→                        onAddAccount = {
 322→                            accountEditing = null
 323→                            accountNew = true
 324→                        },
 325→                        onEditAccount = {
 326→                            accountNew = false
 327→                            accountEditing = it
 328→                        },
 329→                        onArchiveAccount = { archiveAccountTarget = it },
 330→                        onAddCategory = {
 331→                            categoryEditing = null
 332→                            categoryNew = true
 333→                        },
 334→                        onEditCategory = {
 335→                            categoryNew = false
 336→                            categoryEditing = it
 337→                        },
 338→                        onArchiveCategory = { archiveCategoryTarget = it },
 339→                    )
 340→                }
 341→            }
 342→        }
 343→    }
 344→
 345→    captureTarget?.let { capture ->
 346→        CaptureDialog(
 347→            capture = capture,
 348→            accounts = data?.activeAccounts.orEmpty(),
 349→            categories = data?.activeCategories.orEmpty(),
 350→            zone = zone,
 351→            busy = busy,
 352→            externalError = error,
 353→            onDismiss = { if (!busy) captureTarget = null },
 354→            onConfirm = { confirmation, version ->
 355→                runAction("已入账") {
 356→                    repository.confirmCapture(capture.id, confirmation, version)
 357→                    LedgerNotifications.cancel(context, capture.id)
 358→                    captureTarget = null
 359→                    error = null
 360→                }
 361→            },
 362→        )
 363→    }
 364→
 365→    ignoreTarget?.let { capture ->
 366→        AlertDialog(
 367→            onDismissRequest = { if (!busy) ignoreTarget = null },
 368→            title = { Text("忽略这笔草稿？") },
 369→            text = { Text("不会写入账本。可用右上角“撤销”恢复为待确认。") },
 370→            confirmButton = {
 371→                TextButton(
 372→                    enabled = !busy,
 373→                    onClick = {
 374→                        runAction("已忽略") {
 375→                            repository.ignoreCapture(capture.id, capture.version)
 376→                            LedgerNotifications.cancel(context, capture.id)
 377→                            ignoreTarget = null
 378→                        }
 379→                    },
 380→                ) { Text("忽略") }
 381→            },
 382→            dismissButton = { TextButton(onClick = { ignoreTarget = null }, enabled = !busy) { Text("取消") } },
 383→        )
 384→    }
 385→
 386→    deleteTarget?.let { transaction ->
 387→        AlertDialog(
 388→            onDismissRequest = { if (!busy) deleteTarget = null },
 389→            title = { Text("删除这笔账目？") },
 390→            text = { Text("会从统计中移除，并可用“撤销”恢复。") },
 391→            confirmButton = {
 392→                TextButton(
 393→                    enabled = !busy,
 394→                    onClick = {
 395→                        runAction("已删除") {
 396→                            repository.deleteTransaction(transaction.id, transaction.version)
 397→                            deleteTarget = null
 398→                        }
 399→                    },
 400→                ) { Text("删除") }
 401→            },
 402→            dismissButton = { TextButton(onClick = { deleteTarget = null }, enabled = !busy) { Text("取消") } },
 403→        )
 404→    }
 405→
 406→    if (transactionNew || transactionEditing != null) {
 407→        TransactionDialog(
 408→            existing = transactionEditing,
 409→            accounts = data?.accounts.orEmpty(),
 410→            categories = data?.categories.orEmpty(),
 411→            zone = zone,
 412→            nowMillis = repository.now().toEpochMilli(),
 413→            busy = busy,
 414→            externalError = error,
 415→            onDismiss = {
 416→                if (!busy) {
 417→                    transactionNew = false
 418→                    transactionEditing = null
 419→                }
 420→            },
 421→            onSave = { entity, expectedVersion ->
 422→                runAction("已保存") {
 423→                    repository.saveTransaction(entity, expectedVersion)
 424→                    transactionNew = false
 425→                    transactionEditing = null
 426→                    error = null
 427→                }
 428→            },
 429→        )
 430→    }
 431→
 432→    if (accountNew || accountEditing != null) {
 433→        AccountDialog(
 434→            existing = accountEditing,
 435→            busy = busy,
 436→            externalError = error,
 437→            onDismiss = {
 438→                if (!busy) {
 439→                    accountNew = false
 440→                    accountEditing = null
 441→                }
 442→            },
 443→            onSave = { entity, expectedVersion ->
 444→                runAction("已保存") {
 445→                    repository.saveAccount(entity, expectedVersion)
 446→                    accountNew = false
 447→                    accountEditing = null
 448→                    error = null
 449→                }
 450→            },
 451→        )
 452→    }
 453→
 454→    if (categoryNew || categoryEditing != null) {
 455→        CategoryDialog(
 456→            existing = categoryEditing,
 457→            busy = busy,
 458→            externalError = error,
 459→            onDismiss = {
 460→                if (!busy) {
 461→                    categoryNew = false
 462→                    categoryEditing = null
 463→                }
 464→            },
 465→            onSave = { entity, expectedVersion ->
 466→                runAction("已保存") {
 467→                    repository.saveCategory(entity, expectedVersion)
 468→                    categoryNew = false
 469→                    categoryEditing = null
 470→                    error = null
 471→                }
 472→            },
 473→        )
 474→    }
 475→
 476→    archiveAccountTarget?.let { account ->
 477→        AlertDialog(
 478→            onDismissRequest = { if (!busy) archiveAccountTarget = null },
 479→            title = { Text("归档账户“${account.name}”？") },
 480→            text = { Text("新账目不能再选择它，历史账目保留。可用“撤销”恢复。") },
 481→            confirmButton = {
 482→                TextButton(
 483→                    enabled = !busy,
 484→                    onClick = {
 485→                        runAction("已归档") {
 486→                            repository.archiveAccount(account.id, account.version)
 487→                            archiveAccountTarget = null
 488→                        }
 489→                    },
 490→                ) { Text("归档") }
 491→            },
 492→            dismissButton = { TextButton(onClick = { archiveAccountTarget = null }, enabled = !busy) { Text("取消") } },
 493→        )
 494→    }
 495→
 496→    archiveCategoryTarget?.let { category ->
 497→        AlertDialog(
 498→            onDismissRequest = { if (!busy) archiveCategoryTarget = null },
 499→            title = { Text("归档分类“${category.name}”？") },
 500→            text = { Text("新账目不能再选择它，历史账目保留。可用“撤销”恢复。") },
 501→            confirmButton = {
 502→                TextButton(
 503→                    enabled = !busy,
 504→                    onClick = {
 505→                        runAction("已归档") {
 506→                            repository.archiveCategory(category.id, category.version)
 507→                            archiveCategoryTarget = null
 508→                        }
 509→                    },
 510→                ) { Text("归档") }
 511→            },
 512→            dismissButton = { TextButton(onClick = { archiveCategoryTarget = null }, enabled = !busy) { Text("取消") } },
 513→        )
 514→    }
 515→}
