 517→@Composable
 518→private fun NoticeBar(text: String, isError: Boolean, onClose: () -> Unit) {
 519→    Surface(
 520→        modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 6.dp),
 521→        shape = RoundedCornerShape(12.dp),
 522→        color = if (isError) MaterialTheme.colorScheme.errorContainer else MaterialTheme.colorScheme.secondaryContainer,
 523→        contentColor = if (isError) MaterialTheme.colorScheme.onErrorContainer else MaterialTheme.colorScheme.onSecondaryContainer,
 524→    ) {
 525→        Row(Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
 526→            Text(text, Modifier.weight(1f), style = MaterialTheme.typography.bodySmall)
 527→            TextButton(onClick = onClose) { Text("关闭") }
 528→        }
 529→    }
 530→}
 531→
 532→@Composable
 533→private fun PendingTab(
 534→    data: LedgerSnapshot,
 535→    zone: ZoneId,
 536→    busy: Boolean,
 537→    captureEnabled: Boolean,
 538→    accessGranted: Boolean,
 539→    postAllowed: Boolean,
 540→    onToggleCapture: (Boolean) -> Unit,
 541→    onOpenSettings: () -> Unit,
 542→    onRequestPermission: () -> Unit,
 543→    onImport: () -> Unit,
 544→    onManual: () -> Unit,
 545→    onConfirm: (PaymentCaptureEntity) -> Unit,
 546→    onIgnore: (PaymentCaptureEntity) -> Unit,
 547→    onSetup: () -> Unit,
 548→) {
 549→    val pending = data.pendingCaptures
 550→    Column(
 551→        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),
 552→        verticalArrangement = Arrangement.spacedBy(10.dp),
 553→    ) {
 554→        Surface(shape = RoundedCornerShape(16.dp), color = MaterialTheme.colorScheme.surfaceContainer) {
 555→            Column(Modifier.fillMaxWidth().padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
 556→                Text("支付自动捕获", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
 557→                Row(verticalAlignment = Alignment.CenterVertically) {
 558→                    Column(Modifier.weight(1f)) {
 559→                        Text(if (captureEnabled) "已开启" else "已关闭（默认）", style = MaterialTheme.typography.labelLarge)
 560→                        Text("只读取微信、支付宝的支付完成通知，先形成待确认草稿，不直接入账。", style = MaterialTheme.typography.bodySmall)
 561→                    }
 562→                    Switch(checked = captureEnabled, onCheckedChange = onToggleCapture, enabled = !busy)
 563→                }
 564→                Text(
 565→                    "系统通知使用权：${if (accessGranted) "已授予" else "未授予"}",
 566→                    style = MaterialTheme.typography.bodySmall,
 567→                    color = if (accessGranted) MaterialTheme.colorScheme.onSurfaceVariant else MaterialTheme.colorScheme.error,
 568→                )
 569→                if (!accessGranted) TextButton(onClick = onOpenSettings, enabled = !busy) { Text("打开系统通知使用权设置") }
 570→                Text(
 571→                    "应用通知：${if (postAllowed) "允许" else "未允许"}（用于弹出待确认提醒）",
 572→                    style = MaterialTheme.typography.bodySmall,
 573→                    color = if (postAllowed) MaterialTheme.colorScheme.onSurfaceVariant else MaterialTheme.colorScheme.error,
 574→                )
 575→                if (!postAllowed) TextButton(onClick = onRequestPermission, enabled = !busy) { Text("允许应用通知") }
 576→                Text(
 577→                    "累计捕获 ${data.captures.size} 条 · 待确认 ${pending.size} 条",
 578→                    style = MaterialTheme.typography.bodySmall,
 579→                    fontWeight = FontWeight.Medium,
 580→                )
 581→                if (data.activeAccounts.isEmpty() || data.activeCategories.isEmpty()) {
 582→                    Text("确认前需要至少一个账户和一个分类。", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.error)
 583→                    TextButton(onClick = onSetup) { Text("去添加账户与分类") }
 584→                }
 585→                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
 586→                    OutlinedButton(onClick = onImport, enabled = !busy) { Text("导入账单 CSV") }
